-- Use the native -10 reaction and same-faction assist within existing compact radius limits.
-- Only the 30 authored hostile v20 roles participate. This list carries no player faction deltas.
DELIMITER $$
BEGIN NOT ATOMIC
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
    START TRANSACTION;
    IF EXISTS (SELECT 1 FROM npc_faction WHERE id=304102572) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HoT hostile profile ID already in use'; END IF;
    IF EXISTS (SELECT 1 FROM npc_faction_entries WHERE npc_faction_id=304102572) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HoT hostile profile ID already in use'; END IF;
    IF EXISTS (SELECT 1 FROM npc_types WHERE npc_faction_id=304102572) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HoT hostile profile ID already in use'; END IF;
    IF COALESCE((SELECT SHA2(GROUP_CONCAT(h ORDER BY id SEPARATOR ''),256) FROM (SELECT id,SHA2(JSON_ARRAY(`id`,`name`,`lastname`,`level`,`race`,`class`,`bodytype`,`hp`,`mana`,`gender`,`texture`,`helmtexture`,`herosforgemodel`,`size`,`hp_regen_rate`,`hp_regen_per_second`,`mana_regen_rate`,`loottable_id`,`merchant_id`,`greed`,`alt_currency_id`,`npc_spells_id`,`npc_spells_effects_id`,`npc_faction_id`,`adventure_template_id`,`trap_template`,`mindmg`,`maxdmg`,`attack_count`,`npcspecialattks`,`special_abilities`,`aggroradius`,`assistradius`,`face`,`luclin_hairstyle`,`luclin_haircolor`,`luclin_eyecolor`,`luclin_eyecolor2`,`luclin_beardcolor`,`luclin_beard`,`drakkin_heritage`,`drakkin_tattoo`,`drakkin_details`,`armortint_id`,`armortint_red`,`armortint_green`,`armortint_blue`,`d_melee_texture1`,`d_melee_texture2`,`ammo_idfile`,`prim_melee_type`,`sec_melee_type`,`ranged_type`,`runspeed`,`MR`,`CR`,`DR`,`FR`,`PR`,`Corrup`,`PhR`,`see_invis`,`see_invis_undead`,`qglobal`,`AC`,`npc_aggro`,`spawn_limit`,`attack_speed`,`attack_delay`,`findable`,`STR`,`STA`,`DEX`,`AGI`,`_INT`,`WIS`,`CHA`,`see_hide`,`see_improved_hide`,`trackable`,`isbot`,`exclude`,`ATK`,`Accuracy`,`Avoidance`,`slow_mitigation`,`version`,`maxlevel`,`scalerate`,`private_corpse`,`unique_spawn_by_name`,`underwater`,`isquest`,`emoteid`,`spellscale`,`healscale`,`no_target_hotkey`,`raid_target`,`armtexture`,`bracertexture`,`handtexture`,`legtexture`,`feettexture`,`light`,`walkspeed`,`peqid`,`unique_`,`fixed`,`ignore_despawn`,`show_name`,`untargetable`,`charm_ac`,`charm_min_dmg`,`charm_max_dmg`,`charm_attack_delay`,`charm_accuracy_rating`,`charm_avoidance_rating`,`charm_atk`,`skip_global_loot`,`rare_spawn`,`stuck_behavior`,`model`,`flymode`,`always_aggro`,`exp_mod`,`heroic_strikethrough`,`faction_amount`,`keeps_sold_items`,`is_parcel_merchant`,`multiquest_enabled`,`npc_tint_id`),256) h FROM npc_types WHERE id IN (304101816,304101817,304101818,304101882,304101883,304101884,304101933,304101934,304101935,304102018,304102019,304102020,304102023,304102024,304102025,304102028,304102029,304102030,304102033,304102034,304102035,304102038,304102039,304102040,304102043,304102044,304102045,304102048,304102049,304102050)) sq),'')<>'1f482faae4b46def54899fc34811a3d62b8960b142e283b05aa1d8b02f887859' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HoT hostile profile exact actor preimage mismatch'; END IF;
    INSERT INTO npc_faction (id,name,primaryfaction,ignore_primary_assist) VALUES (304102572,'HoT authored field mission hostiles',-10,0);
    IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HoT hostile profile faction insert count mismatch'; END IF;
    UPDATE npc_types SET npc_faction_id=304102572 WHERE id IN (304101816,304101817,304101818,304101882,304101883,304101884,304101933,304101934,304101935,304102018,304102019,304102020,304102023,304102024,304102025,304102028,304102029,304102030,304102033,304102034,304102035,304102038,304102039,304102040,304102043,304102044,304102045,304102048,304102049,304102050) AND npc_faction_id=0;
    IF ROW_COUNT()<>30 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='HoT hostile profile combat role count mismatch'; END IF;
    COMMIT;
END$$
DELIMITER ;
